// Anatomy of the 16.6ms Frame Budget
const TARGET_FPS = 60;
const FRAME_BUDGET_MS = 1000 / TARGET_FPS; // 16.666ms

function evaluateFramePerformance(taskDurationsMs) {
  let accumulatedTime = 0;
  let droppedFrames = 0;
  const frameLogs = [];

  for (let i = 0; i < taskDurationsMs.length; i++) {
    const duration = taskDurationsMs[i];
    accumulatedTime += duration;

    // Calculate how many frame intervals this task spans
    const framesConsumed = Math.ceil(duration / FRAME_BUDGET_MS);
    const isJank = duration > FRAME_BUDGET_MS;

    if (isJank) {
      const missed = framesConsumed - 1;
      droppedFrames += missed;
      frameLogs.push('[Frame ' + (i + 1) + '] JANK! Duration: ' + duration + 'ms (Missed ' + missed + ' frames)');
    } else {
      const headroom = (FRAME_BUDGET_MS - duration).toFixed(2);
      frameLogs.push('[Frame ' + (i + 1) + '] PASS: Duration: ' + duration + 'ms (Headroom: ' + headroom + 'ms)');
    }
  }

  return {
    totalTime: accumulatedTime,
    droppedFrames: droppedFrames,
    logs: frameLogs
  };
}

