// Simulating the HTML5 setTimeout 4ms Clamping Penalty
function simulateTimerSlicing(numSlices, sliceDurationMs) {
  let simulatedClock = 0;
  let activeExecutionTime = 0;
  let idleClampTime = 0;
  const trace = [];

  for (let nestingLevel = 1; nestingLevel <= numSlices; nestingLevel++) {
    // HTML5 Standard: Once nesting level > 5, timer clamped to min 4ms
    const clampDelay = nestingLevel > 5 ? 4.0 : 0.0;

    // Time spent waiting for event loop turn
    simulatedClock += clampDelay;
    idleClampTime += clampDelay;

    // Time spent executing the actual JavaScript slice
    simulatedClock += sliceDurationMs;
    activeExecutionTime += sliceDurationMs;

    if (nestingLevel <= 3 || nestingLevel >= numSlices - 1) {
      trace.push('Slice #' + nestingLevel + ': Work=' + sliceDurationMs + 'ms | Clamp=' + clampDelay + 'ms | Clock=' + simulatedClock.toFixed(1) + 'ms');
    } else if (nestingLevel === 4) {
      trace.push('... [Slices 4 to ' + (numSlices - 2) + ' clamped at 4ms each] ...');
    }
  }

  return {
    slices: numSlices,
    activeWorkMs: activeExecutionTime,
    wastedClampMs: idleClampTime,
    totalWallClockMs: simulatedClock,
    overheadPercentage: ((idleClampTime / simulatedClock) * 100).toFixed(1),
    trace: trace
  };
}

