// Cooperative Work Loop with shouldYield() Heuristic
class CooperativeWorkLoop {
  constructor(unitsOfWork) {
    this.units = unitsOfWork;
    this.currentIndex = 0;
    this.sliceStartTime = 0;
    this.YIELD_INTERVAL_MS = 5; // 5ms React Scheduler default
    this.slicesCount = 0;
  }

  // The core React Scheduler heuristic
  shouldYield() {
    const elapsed = Date.now() - this.sliceStartTime;
    return elapsed >= this.YIELD_INTERVAL_MS;
  }

  // Starts or resumes processing the fiber queue
  run() {
    this.slicesCount++;
    this.sliceStartTime = Date.now();
    console.log('[WorkLoop] Slice #' + this.slicesCount + ' started at index ' + this.currentIndex);

    while (this.currentIndex < this.units.length) {
      // Process one individual unit of work (e.g. reconcile one Fiber)
      const unit = this.units[this.currentIndex];
      this.processFiber(unit);
      this.currentIndex++;

      // Check if time-slice budget expired and more work remains
      if (this.shouldYield() && this.currentIndex < this.units.length) {
        console.log('[WorkLoop] shouldYield() returned TRUE | Pausing at index ' + this.currentIndex);
        return false; // Work incomplete, yielded
      }
    }

    console.log('[WorkLoop] All ' + this.units.length + ' fibers processed across ' + this.slicesCount + ' slice(s)!');
    return true; // Complete
  }

  processFiber(fiber) {
    console.log('  -> Reconciled Fiber: ' + fiber.name + ' (id=' + fiber.id + ')');
  }
}

