// Priority Starvation and Expiration Escalation Engine
class LaneStarvationScheduler {
  constructor() {
    this.pendingLanes = 0;
    this.expiredLanes = 0;
    this.expirationTimes = {};
    this.currentTime = 1000; // Simulated virtual start clock
  }

  // Schedule an update in a specific lane with a timeout
  scheduleLane(lane, timeoutMs) {
    this.pendingLanes |= lane;
    this.expirationTimes[lane] = this.currentTime + timeoutMs;
    console.log('[Schedule] Lane 0b' + lane.toString(2) + ' scheduled. Expires at: ' + this.expirationTimes[lane] + 'ms');
  }

  // Advance virtual time and audit for starved lanes
  advanceTimeAndCheck(elapsedMs) {
    this.currentTime += elapsedMs;
    console.log('\n--- Virtual Clock Advanced to ' + this.currentTime + 'ms ---');

    // Check each pending lane for expiration
    for (const laneStr in this.expirationTimes) {
      const lane = Number(laneStr);
      if ((this.pendingLanes & lane) !== 0) {
        if (this.currentTime >= this.expirationTimes[lane]) {
          // Promote starved lane to expired (Sync) status!
          this.expiredLanes |= lane;
          console.log('[ESCALATION] Lane 0b' + lane.toString(2) + ' has EXPIRED! Promoted to synchronous urgency!');
        }
      }
    }
  }

  getNextWorkLane() {
    // If any lanes have expired, execute them immediately
    if (this.expiredLanes !== 0) {
      const urgentLane = this.expiredLanes & -this.expiredLanes;
      return { lane: urgentLane, isExpired: true };
    }
    // Otherwise execute normal highest-priority lane
    const normalLane = this.pendingLanes & -this.pendingLanes;
    return { lane: normalLane, isExpired: false };
  }
}

