// Production 31-Bit Bitmask Lane Scheduler
class BitmaskLaneScheduler {
  constructor() {
    this.pendingLanes = 0;
    this.expiredLanes = 0;
    this.expirationTimes = {};
    this.virtualClock = 0;
    this.executionLog = [];
  }

  // Bitmask definitions
  static SyncLane            = 0b00000001; // Bit 0
  static InputContinuousLane = 0b00000010; // Bit 1
  static DefaultLane         = 0b00000100; // Bit 2
  static TransitionLane      = 0b00001000; // Bit 3
  static IdleLane            = 0b00010000; // Bit 4

  schedule(taskName, lane, timeoutMs) {
    this.pendingLanes |= lane;
    this.expirationTimes[lane] = this.virtualClock + timeoutMs;
    console.log('[Schedule] "' + taskName + '" queued into Lane 0b' + lane.toString(2));
  }

  getHighestPriorityLane() {
    // Expired lanes have absolute priority
    if (this.expiredLanes !== 0) {
      return this.expiredLanes & -this.expiredLanes;
    }
    // Otherwise pick highest priority pending lane
    return this.pendingLanes & -this.pendingLanes;
  }

  auditStarvation(currentClock) {
    this.virtualClock = currentClock;
    for (const laneStr in this.expirationTimes) {
      const lane = Number(laneStr);
      if ((this.pendingLanes & lane) !== 0 && this.virtualClock >= this.expirationTimes[lane]) {
        this.expiredLanes |= lane;
        console.log('[Audit] Starvation detected! Lane 0b' + lane.toString(2) + ' escalated to Expired');
      }
    }
  }

  flushNextLane() {
    const lane = this.getHighestPriorityLane();
    if (lane === 0) {
      console.log('[WorkLoop] All lanes committed!');
      return false;
    }

    const isExpired = (this.expiredLanes & lane) !== 0;
    console.log('[Execute] Reconciling Lane 0b' + lane.toString(2) + ' (Urgent/Expired: ' + isExpired + ')');

    // Clear lane from pending and expired bitmasks
    this.pendingLanes &= ~lane;
    this.expiredLanes &= ~lane;
    return true;
  }
}

