class ProductionTransitionEngine {
  constructor() {
    this.isPending = false;
    this.urgentValue = 'Hello';
    this.transitionValue = 'Hello';
    this.inFlightTransition = null;
    this.telemetry = {
      urgentCount: 0,
      transitionCount: 0,
      abortedCount: 0
    };
  }

  // Urgent update (SyncLane): Immediate execution, preempts transitions
  setUrgent(newVal) {
    this.urgentValue = newVal;
    this.telemetry.urgentCount++;
    console.log('[Urgent Sync] Input text updated to: "' + this.urgentValue + '" (Instant)');

    // Preemption check: If a background transition is in flight, abort it!
    if (this.inFlightTransition && !this.inFlightTransition.done) {
      console.log('[PREEMPTION] Aborting in-flight transition for: "' + this.inFlightTransition.targetVal + '"');
      this.inFlightTransition.aborted = true;
      this.telemetry.abortedCount++;
      this.inFlightTransition = null;
    }
  }

  // Non-urgent update (TransitionLane): Sliced background execution
  startTransition(targetVal, totalSteps) {
    this.isPending = true;
    console.log('[Transition] startTransition() called | isPending = true');

    const transitionObj = {
      targetVal: targetVal,
      totalSteps: totalSteps,
      currentStep: 0,
      done: false,
      aborted: false
    };
    this.inFlightTransition = transitionObj;

    // Simulate first cooperative slice (step 1 of 2)
    this.processSlice(transitionObj);
    return transitionObj;
  }

  processSlice(t) {
    if (t.aborted) return;

    t.currentStep++;
    console.log('  -> [Slice] Processed step ' + t.currentStep + '/' + t.totalSteps + ' for: "' + t.targetVal + '"');

    if (t.currentStep >= t.totalSteps) {
      t.done = true;
      this.transitionValue = t.targetVal;
      this.isPending = false;
      this.inFlightTransition = null;
      this.telemetry.transitionCount++;
      console.log('[Transition Commit] Finished! transitionValue = "' + this.transitionValue + '" | isPending = false');
    }
  }
}

